CREATE TABLE "AssistantRequest" (id TEXT PRIMARY KEY, "companyId" TEXT NOT NULL REFERENCES "Company"(id), "userId" TEXT NOT NULL REFERENCES "User"(id), feature TEXT NOT NULL, model TEXT NOT NULL, "inputHash" TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'PROCESSING', "budgetMicros" INTEGER NOT NULL CHECK ("budgetMicros">0), "actualMicros" INTEGER CHECK ("actualMicros">=0), "resultId" TEXT UNIQUE REFERENCES "AIResult"(id), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CHECK (state IN ('PROCESSING','SUCCEEDED','FAILED','UNKNOWN','CANCELLED')));
CREATE INDEX "AssistantRequest_companyId_createdAt_idx" ON "AssistantRequest"("companyId","createdAt");
ALTER TABLE "Delivery" ADD COLUMN "contactAuthorized" BOOLEAN NOT NULL DEFAULT false, ADD COLUMN recipient TEXT;
